# v4.6.1 — retiro de superficies legacy ya sin callers activos.
# No toca datos, Neon, Historia, AZUR, WhatsApp, agenda, facturación ni impresión.
# ---------------------------------------------------------------------------
_LEGACY_DISABLED_ROUTE_PATHS = frozenset({
    "/api/mobile/remote/status",
    "/api/mobile/remote/quick/start",
    "/api/mobile/remote/stable/restart",
    "/api/mobile/remote/stop",
    "/api/update/apply",
})

def _remove_legacy_dead_routes() -> int:
    before = len(app.router.routes)
    app.router.routes[:] = [
        route for route in app.router.routes
        if getattr(route, "path", None) not in _LEGACY_DISABLED_ROUTE_PATHS
    ]
    # Si OpenAPI llegó a generarse durante el import, forzar regeneración.
    try:
        app.openapi_schema = None
    except Exception:
        pass
    return before - len(app.router.routes)

LEGACY_DEAD_ROUTES_REMOVED = _remove_legacy_dead_routes()
